@SpringBootApplication
public class UserServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(UserServiceApplication.class, args);
    }
}

@RestController
class HealthController {
    @GetMapping("/health")
    public Map<String, String> healthCheck() {
        // Load balancer calls this every 10 seconds
        return Map.of("status", "UP", "instance", getInstanceId());
    }

    private String getInstanceId() {
        return System.getenv("INSTANCE_ID"); // Set by ECS
    }
}

@RestController
@RequestMapping("/api/users")
class UserController {
    @GetMapping("/{id}")
    public User getUser(@PathVariable Long id) {
        // This method runs on whichever instance the load balancer chose
        return new User(id, "Alice");
    }
}

record User(Long id, String name) {}

// AWS Application Load Balancer distributes traffic across 3 instances
// If health check fails, that instance is removed from rotation

@Service
class OrderService {
    private final OrderRepository repository; // RDS PostgreSQL
    private final AmazonS3 s3Client; // AWS SDK for S3
    private final AmazonSQS sqsClient; // AWS SDK for SQS

    OrderService(OrderRepository repository, AmazonS3 s3Client, AmazonSQS sqsClient) {
        this.repository = repository;
        this.s3Client = s3Client;
        this.sqsClient = sqsClient;
    }

    public Order processOrder(OrderRequest request) {
        var order = new Order(null, request.item(), request.price());
        var saved = repository.save(order); // Saved to RDS

        // Upload invoice PDF to S3
        var invoice = generateInvoicePdf(saved);
        s3Client.putObject("invoices-bucket", saved.id() + ".pdf", invoice);

        // Send notification message to SQS
        var message = "Order " + saved.id() + " created";
        sqsClient.sendMessage("order-notifications", message);

        return saved;
    }
}

record Order(Long id, String item, BigDecimal price) {}
record OrderRequest(String item, BigDecimal price) {}

# main.tf - Terraform file for ECS deployment
resource "aws_ecs_cluster" "app_cluster" {
  name = "order-service-cluster"
}

resource "aws_ecs_task_definition" "order_service" {
  family = "order-service"
  container_definitions = jsonencode([{
    name      = "order-service"
    image     = "mycompany/order-service:latest"
    cpu       = 256
    memory    = 512
    portMappings = [{ containerPort = 8080 }]
  }])
}

resource "aws_db_instance" "postgres" {
  engine         = "postgres"
  instance_class = "db.t3.micro" # Managed RDS instance
  allocated_storage = 20
  db_name        = "orders_db"
}

resource "aws_s3_bucket" "invoices" {
  bucket = "order-invoices-prod" # S3 for file storage
}

# Run: terraform apply
# AWS creates all these resources automatically
